import{_ as n,y as i,a as l,o as g,a2 as o,D as a,g as e,I as r}from"./chunks/framework.DCcmcJcL.js";const T=JSON.parse('{"title":"Data Transfer","description":"","frontmatter":{},"headers":[],"relativePath":"settings/data-transfer.md","filePath":"settings/data-transfer.md","lastUpdated":1789441803000}'),d={name:"settings/data-transfer.md"};function h(p,t,m,u,c,f){const s=i("ImagePopup");return g(),l("div",null,[t[4]||(t[4]=o('<h1 id="data-transfer" tabindex="-1">Data Transfer <a class="header-anchor" href="#data-transfer" aria-label="Permalink to &quot;Data Transfer&quot;">​</a></h1><p>Data transfer imports products, customers and tax rates in bulk from a file, so you don&#39;t have to enter a large catalog one record at a time. Once you start an import, Bagisto runs every step on its own, and a progress bar at the top of the page shows the step it has reached.</p><h2 id="what-you-can-import" tabindex="-1">What you can import <a class="header-anchor" href="#what-you-can-import" aria-label="Permalink to &quot;What you can import&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Each row is matched by</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Products</strong></td><td>SKU</td><td>Every product type except downloadable products.</td></tr><tr><td><strong>Customers</strong></td><td>Email address</td><td>The customer group code in the file must already exist.</td></tr><tr><td><strong>Tax Rates</strong></td><td>Identifier</td><td>A row has a single zip code or a zip range. Without a range, the zip code is required, so use <code>*</code> for every postcode. The rate must be more than 0. See <a href="./taxes.html">Taxes</a>.</td></tr></tbody></table><p>The sample file for each type shows the columns it expects.</p><h2 id="your-imports" tabindex="-1">Your imports <a class="header-anchor" href="#your-imports" aria-label="Permalink to &quot;Your imports&quot;">​</a></h2><p>Go to <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong> to see every import with its <strong>ID</strong>, <strong>State</strong>, <strong>Uploaded File</strong>, <strong>Error File</strong>, <strong>Started At</strong>, <strong>Completed At</strong> and <strong>Summary</strong>, which counts the records created, updated and deleted. <strong>State</strong> shows where each import is as a single word, such as <code>pending</code>, <code>processing</code> or <code>completed</code>. Click a file to download it.</p>',7)),a(s,{src:"/images/settings/imports.png",alt:"Imports grid with a completed customer import and its summary"}),t[5]||(t[5]=o('<p>Each row has these actions:</p><ul><li><strong>View Progress</strong> or <strong>Import</strong>: both open the import page.</li><li><strong>Edit</strong> to change the import and run it again. See <a href="#edit-or-delete-an-import">Edit or delete an import</a>.</li><li><strong>Delete</strong> to remove the import and its files.</li></ul><h2 id="create-an-import" tabindex="-1">Create an import <a class="header-anchor" href="#create-an-import" aria-label="Permalink to &quot;Create an import&quot;">​</a></h2>',3)),e("ol",null,[t[1]||(t[1]=o('<li><p>Go to <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong>.</p></li><li><p>Click <strong>Create Import</strong>.</p></li><li><p>Choose the <strong>Type</strong> of records to import: <strong>Products</strong>, <strong>Customers</strong> or <strong>Tax Rates</strong>.</p></li><li><p>Click the arrow beside <strong>Download Sample</strong> and choose <strong>CSV</strong>, <strong>XLS</strong>, <strong>XLSX</strong> or <strong>XML</strong> to get a file with the expected columns. Prepare your file in the same layout.</p></li><li><p>Choose the <strong>File</strong>. CSV, XLS, XLSX and XML files are accepted.</p></li><li><p>For products, choose where the images named in your file are found under <strong>Product Images</strong>. See <a href="#product-images">Product images</a>.</p></li>',6)),e("li",null,[t[0]||(t[0]=o('<p>In <strong>Settings</strong>, check the <strong>Action</strong>, <strong>Validation Strategy</strong>, <strong>Allowed Errors</strong>, <strong>Field Separator</strong> and <strong>Process In Queue</strong>. See <a href="#import-settings">Import settings</a>.</p>',1)),a(s,{src:"/images/settings/create-import.png",alt:"Create Import page for a product import"})]),t[2]||(t[2]=e("li",null,[e("p",null,[r("Click "),e("strong",null,"Import"),r(".")])],-1)),t[3]||(t[3]=e("li",null,[e("p",null,[r("In the message "),e("em",null,"The import will start as soon as this is saved. Do you want to continue?"),r(", click "),e("strong",null,"Agree"),r(".")])],-1))]),t[6]||(t[6]=o('<p>The message <em>Import created successfully.</em> appears, the import page opens and the import starts.</p><h2 id="import-settings" tabindex="-1">Import settings <a class="header-anchor" href="#import-settings" aria-label="Permalink to &quot;Import settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Action</strong></td><td><strong>Create/Update</strong> adds new records and updates the ones that already exist. <strong>Delete</strong> removes the records listed in the file.</td></tr><tr><td><strong>Validation Strategy</strong></td><td>Invalid rows are always left out. <strong>Stop on Errors</strong> stops the import after validation when the file has more errors than <strong>Allowed Errors</strong>. <strong>Skip Errors</strong> imports the valid rows however many errors there are.</td></tr><tr><td><strong>Allowed Errors</strong></td><td>With <strong>Stop on Errors</strong>, how many errors the file can have before the import stops. The default is <code>10</code>.</td></tr><tr><td><strong>Field Separator</strong></td><td>The character between columns in a CSV file. The default is a comma.</td></tr><tr><td><strong>Process In Queue</strong></td><td>Runs the import in the background, which suits large files. See below.</td></tr></tbody></table><h3 id="process-in-queue" tabindex="-1">Process in queue <a class="header-anchor" href="#process-in-queue" aria-label="Permalink to &quot;Process in queue&quot;">​</a></h3><p>With <strong>Process In Queue</strong> on, the import runs in the background, and you can leave the page. Switch it on only when a developer has set your store up to run imports in the background. See <a href="./../getting-started/scheduled-tasks.html#work-that-goes-through-the-queue">Work that goes through the queue</a>.</p><ul><li>If that isn&#39;t set up, the import stops after validation with the message <em>Please change your queue driver to &quot;database&quot; or &quot;redis&quot; to start the import process.</em></li><li>If it&#39;s set up but not running, the progress bar doesn&#39;t move.</li></ul><p>In either case, run the import again without the queue:</p><ol><li>Go to <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong>.</li><li>Click <strong>Edit</strong> on the import.</li><li>Switch <strong>Process In Queue</strong> off.</li><li>Click <strong>Import</strong>.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>With <strong>Process In Queue</strong> off, your browser runs the import in short steps. If you close the page, the import pauses, and it continues from the same step when you open the import again.</p><p>An import stops at validation, whatever the strategy, if every row is invalid.</p><h2 id="product-images" tabindex="-1">Product images <a class="header-anchor" href="#product-images" aria-label="Permalink to &quot;Product images&quot;">​</a></h2><p>A product file names each product&#39;s images in its <strong>images</strong> column. Under <strong>Product Images</strong>, choose where Bagisto finds them:</p><ul><li><strong>Image links in the file</strong> (recommended): put the full address of each image, starting with <code>http://</code> or <code>https://</code>, in the <strong>images</strong> column. Separate several images with commas. The images are downloaded before any record is written, so nothing has to be placed on the server first. An image that can&#39;t be downloaded is left out, and the product is imported without it.</li><li><strong>Upload a ZIP of images</strong>: upload one archive that contains every image, and put the file names in the <strong>images</strong> column. The archive can be up to 100 MB, though your server may allow less. After you choose this option, <strong>Download sample images</strong> gives you an archive that matches the sample file.</li><li><strong>Images already on the server</strong>: if you can place files on the server, put the images in a folder under the store&#39;s import directory and enter the folder name in the path field below the option. The hint below the field shows the exact location.</li></ul><p>With a ZIP or a server folder, a row whose image file isn&#39;t found, or whose <strong>images</strong> column holds a web address, is reported as an error and left out.</p><p><strong>Images already on the server</strong> is selected at first, and its path is required while it&#39;s selected. If your file has no images, choose <strong>Image links in the file</strong>.</p>',15)),a(s,{src:"/images/settings/import-image-source.png",alt:"Product Images options on the Create Import page"}),t[7]||(t[7]=o('<p>Your choice is saved with the import. When you edit an import that has a ZIP archive, the page shows its name and how many images are ready; choosing a new archive replaces them.</p><h2 id="follow-the-import" tabindex="-1">Follow the import <a class="header-anchor" href="#follow-the-import" aria-label="Permalink to &quot;Follow the import&quot;">​</a></h2><p>The progress bar on the import page shows these steps:</p><ul><li><strong>Validate</strong> – the file is read and each row is checked.</li><li><strong>Images</strong> – the image links in the file are downloaded before any record is written. This step appears only for products with <strong>Image links in the file</strong>.</li><li><strong>Create</strong> or <strong>Delete</strong> – the records are written, or removed when the action is <strong>Delete</strong>.</li><li><strong>Link</strong> – imported products are connected, such as configurable variants, grouped and bundle products, booking details, and related, cross-sell and up-sell products.</li><li><strong>Index</strong> – price, inventory and search data are rebuilt.</li></ul><p><strong>Images</strong>, <strong>Link</strong> and <strong>Index</strong> appear only for product imports that create or update. A customer or tax rate import shows <strong>Validate</strong> and <strong>Create</strong>, and any import with the <strong>Delete</strong> action shows <strong>Validate</strong> and <strong>Delete</strong>.</p><p>When every step is done, the message <em>Congratulations! Your import was successful.</em> appears with the <strong>Total Records Created</strong>, <strong>Total Records Updated</strong> and <strong>Total Records Deleted</strong>.</p>',6)),a(s,{src:"/images/settings/import-done.png",alt:"Import page after a successful customer import, with the Validate and Create steps complete"}),t[8]||(t[8]=o('<p>The imported records appear under the matching menu, such as <strong>Customers &gt;&gt; Customers</strong> for a customer import (see <a href="./../customer/create-customer.html">Customers</a>) or <strong>Catalog &gt;&gt; Products</strong> for a product import (see <a href="./../product-types/products.html">Products</a>).</p><h3 id="if-the-file-has-errors" tabindex="-1">If the file has errors <a class="header-anchor" href="#if-the-file-has-errors" aria-label="Permalink to &quot;If the file has errors&quot;">​</a></h3><p>After validation, the page shows the <strong>Total Rows Processed</strong>, <strong>Total Invalid Rows</strong> and <strong>Total Errors</strong>, and lists the first errors.</p><ul><li><em>Your import can proceed, but some rows will be skipped. Review the errors below or download the full report.</em> means the valid rows are imported and the invalid ones left out. The import continues on its own.</li><li><em>Your import is invalid. Please fix the following errors and try again.</em> means the import has stopped.</li><li><em>The import could not be processed. Please check the file and try again.</em> means a step couldn&#39;t run.</li></ul><p>Click <strong>Download Full Report</strong> to see every error. If the column headings in the file are wrong, the errors are shown on the page only. To try again, fix your file and <a href="#edit-or-delete-an-import">edit the import</a> with the new file.</p><p>When an import runs in the queue and some batches don&#39;t finish, the message says how many didn&#39;t. Ask your developer to check the store&#39;s error log, then import those rows again.</p><h3 id="come-back-to-a-running-import" tabindex="-1">Come back to a running import <a class="header-anchor" href="#come-back-to-a-running-import" aria-label="Permalink to &quot;Come back to a running import&quot;">​</a></h3><p>You don&#39;t have to wait on the page. On <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong>, click <strong>View Progress</strong> or <strong>Import</strong> on the import&#39;s row to open its page again.</p><h2 id="edit-or-delete-an-import" tabindex="-1">Edit or delete an import <a class="header-anchor" href="#edit-or-delete-an-import" aria-label="Permalink to &quot;Edit or delete an import&quot;">​</a></h2><p>To run an import again with a corrected file or other settings:</p><ol><li>Go to <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong>.</li><li>Click <strong>Edit</strong> on the import. The <strong>Edit Import</strong> page shows the <strong>Current Uploaded File</strong>.</li><li>Optionally, choose a new <strong>File</strong> or change the settings.</li><li>Click <strong>Import</strong>.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>The message <em>Import updated successfully.</em> appears and the import starts again from <strong>Validate</strong>. The results of the previous run are cleared.</p><p>The <strong>Edit Import</strong> page shows <strong>Product Images</strong> for every type. For a customer or tax rate import, ignore it.</p><p>To remove an import and its files:</p><ol><li>Go to <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong>.</li><li>Click <strong>Delete</strong> on the import&#39;s row.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>The message <em>Import deleted successfully.</em> appears. The records it already imported are kept.</p>',16))])}const y=n(d,[["render",h]]);export{T as __pageData,y as default};
